-- Import des courriers arrivées 2009
-- Source : 2009.xlsx (feuille 2009).
-- La colonne CATEGORIES vaut partout « Demande SERVICES ».
-- txt_categorie est déduite de la désignation, comme en 2012, 2014 et 2016.
--
--   N°                 -> txt_numdordre (00001/jj-mm-aaaa) et txt_numcourier
--   DATE CREATION      -> dt_datearrivee et dt_datecourier
--   référence          -> « <N°> du jj-mm-aaaa » (pas de colonne correspondance)
--   PRENOMS + NOM      -> txt_prenomNom et txt_expediteur
--   DESIGNATIONS       -> txt_objet, puis txt_designation et txt_categorie
--   N° TF              -> txt_numTitreFoncier, ou txt_numTitreMere si TF EN GRD est différent
--   TF EN GRD          -> txt_numTitreFoncier
--   N° LOT             -> txt_numLot
--   SITUATION          -> txt_lotissement
--   AGENTS TRAITEURS   -> txt_agenttraiteur
--   OBSERVATIONS       -> txt_observation
--
-- txt_typecourrier = BE si la désignation commence par « BE », sinon Individuel
-- txt_nombrepiece = 1
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Références en doublon : suffixe [n° d'ordre]
-- Lignes importées : 2085
--
-- Répartition des catégories :
--    2001  Demande SERVICES
--      70  Information
--       9  Convocation - Invitation
--       3  Réclamation - Signalement
--       2  Réquisition - Instruction
-- Désignations :
--     838  Morcellements
--     525  Autorisation de construction
--     180  Demande de Cession définitive
--     165  Demande de Régularisation par voie de Bail
--      75  Demande de terrain/Echange
--      63  Demande de délimitation
--      37  Litiges
--      35  Autres
--      22  Duplication de CIC
--      19  Autorisation de lotir
--      15  Demande d'évaluation
--      15  Note de service
--      13  Réceptions de lotissements
--      13  Demande d'états des lieux
--      12  Demande d'extraits de plan
--      10  Circulaire
--       7  Autorisation de morceler
--       6  Demande de situation foncière
--       6  Réunion
--       4  Réquisition d'immatriculation
--       4  Rapport
--       4  Tribunal
--       3  Décision - Arrêté
--       3  Formation
--       3  Plainte
--       2  Demande de Titre foncier
--       2  Instruction à suivre
--       2  Document administratif
--       1  Demande d'attestation du Cadastre
--       1  Transmission lettre

SET NAMES utf8mb4;

START TRANSACTION;







COMMIT;
